package pe.cruzroja.convocatorias.attendance.domain; import java.time.*; import java.util.UUID; public class AttendanceRecord {public static final int LATE_TOLERANCE_MINUTES=15; private final UUID id,enrollmentId,volunteerId,calloutId,responsibleId; private final LocalDateTime checkIn,checkOut; private final AttendanceStatus status; private boolean signed; public AttendanceRecord(UUID id,UUID enrollmentId,UUID volunteerId,UUID calloutId,LocalDateTime start,LocalDateTime checkIn,LocalDateTime checkOut,UUID responsibleId,boolean absent){if(id==null||enrollmentId==null||volunteerId==null||calloutId==null||responsibleId==null)throw new IllegalArgumentException("Asistencia inválida");if(absent&&(checkIn!=null||checkOut!=null))throw new IllegalArgumentException("Una ausencia no registra horas");if(!absent&&(checkIn==null||checkOut==null||!checkOut.isAfter(checkIn)))throw new IllegalArgumentException("Horario de asistencia inválido");this.id=id;this.enrollmentId=enrollmentId;this.volunteerId=volunteerId;this.calloutId=calloutId;this.checkIn=checkIn;this.checkOut=checkOut;this.responsibleId=responsibleId;this.status=absent?AttendanceStatus.AUSENTE:(checkIn.isAfter(start.plusMinutes(LATE_TOLERANCE_MINUTES))?AttendanceStatus.TARDE:AttendanceStatus.PRESENTE);} public void sign(){signed=true;} public AttendanceStatus status(){return status;} public boolean signed(){return signed;} public double hours(){return new ServiceHoursCalculator().calculate(checkIn,checkOut);} }
